{
  "Article": {
    "Intro": "Princess Märtha Louise of Norway, known for her claimed psychic abilities, is the daughter of one of the longest-reigning monarchs in Europe. Her husband, Durek Verrett, is a self-proclaimed sixth-generation shaman hailing from California. Their wedding ceremony in the gloomy town of Geiranger, Norway, this Saturday was an extraordinary royal event which nonetheless drew a keen crowd eager to sight the bride.",
    "Details": {
      "BrideInfo": "Märtha Louise, age 52, is the singular daughter of King Harald and Queen Sonja and is fourth in succession to the Norwegian crown.",
      "GroomInfo": "Her partner Verrett, 49, was married to her in a traditional Norwegian church ritual attended by a notable crossover of royals and celebrities at the luxurious four-star Hotel Union tucked in a quaint village beneath the Geiranger fjord.",
      "Bridesmaids": "The royal bride was accompanied by seven bridesmaids which also included her teenage girls, Leah and Emma Behn, from her initial marriage to renowned Norwegian writer Ari Behn, who she divorced in 2017.",
      "GuestList": "Among the 350 high-profile guests were the bride's brother Crown Prince Haakon with his partner Crown Princess Mette-Marit, Sweden's Crown Princess Victoria and her consort Prince Daniel and Netherlands' royal couple Prince Constantijn and Princess Laurentien."
    },
    "Background": {
      "Bride": {
        "RoyalLife": "Princess Märtha Louise's life as a royal has been anything but customary, evident in her declaration of psychic abilities. She ran a healing school for a decade, teaching people to communicate with heavenly entities.",
        "Decision": "In 2022, she articulated her decision of retiring from official royal responsibilities to concentrate on her and Verrett's commercial ventures and set a distinct separation between their professional life and the royal house of Norway."
      },
      "Groom": {
        "Identity": "Verrett labels himself a 'servant of God' and 'energy activator' on social media platforms like Instagram.",
        "NotableClients": "Among his famous clientele is the founder of Goop, Gwyneth Paltrow, who he identifies as a 'soul sister'."
      }
    }
  }
}```

